--
-- Name: advice_cache_get(text); Type: FUNCTION; Schema: iberia; Owner: -
--

CREATE FUNCTION iberia.advice_cache_get(p_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare a jsonb;
begin
  if not iberia.sees_company() then
    raise exception 'not allowed' using errcode = 'insufficient_privilege';
  end if;
  -- The age check lives here rather than in the edge function, so the clock
  -- that decides it is the database's and not whichever machine happened to
  -- serve the request.
  select advice into a from iberia.advice_cache
   where id = p_id and created_at > now() - interval '24 hours';
  return a;
end $$;


--
-- Name: advice_cache_put(text, jsonb, text, text); Type: FUNCTION; Schema: iberia; Owner: -
--

CREATE FUNCTION iberia.advice_cache_put(p_id text, p_advice jsonb, p_lang text, p_model text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not iberia.sees_company() then
    raise exception 'not allowed' using errcode = 'insufficient_privilege';
  end if;
  insert into iberia.advice_cache (id, advice, lang, model, created_at)
  values (p_id, p_advice, coalesce(p_lang, 'en'), p_model, now())
  on conflict (id) do update
    set advice = excluded.advice, lang = excluded.lang,
        model = excluded.model, created_at = now();

  -- Kept small on the way past rather than by a scheduled job nobody
  -- remembers exists. A week of sheets is more history than anything reads.
  delete from iberia.advice_cache where created_at < now() - interval '7 days';
end $$;


--
-- Name: advice_facts(); Type: FUNCTION; Schema: iberia; Owner: -
--

CREATE FUNCTION iberia.advice_facts() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  j jsonb; n_all int; n_cost int; n_decided int;
  won_n int; won_eur numeric; lost_n int; lost_eur numeric;
  open_n int; open_eur numeric; today date := current_date;
  big_lost numeric;
begin
  -- An employee cannot see revenue anywhere else in the application and must
  -- not receive it wrapped in a paragraph of advice either -- and neither may
  -- a manager, whose money gate stops at one job. This sheet is the whole
  -- company. See sees_company() above.
  if not iberia.sees_company() then
    raise exception 'not allowed' using errcode = 'insufficient_privilege';
  end if;

  select count(*), count(cost_ex_vat) into n_all, n_cost from iberia.enquiries;
  select
    count(*) filter (where status = 'Gautas PO'),
    coalesce(sum(price_ex_vat) filter (where status = 'Gautas PO'), 0),
    count(*) filter (where status = 'Atmesta užklausa'),
    coalesce(sum(price_ex_vat) filter (where status = 'Atmesta užklausa'), 0),
    count(*) filter (where status = 'Vykdoma'),
    coalesce(sum(price_ex_vat) filter (where status = 'Vykdoma'), 0),
    coalesce(max(price_ex_vat) filter (where status = 'Atmesta užklausa'), 0)
  into won_n, won_eur, lost_n, lost_eur, open_n, open_eur, big_lost
  from iberia.enquiries;
  n_decided := won_n + lost_n;

  j := jsonb_build_object('generated_at', to_char(now(), 'YYYY-MM-DD'), 'currency', 'EUR');

  j := j || jsonb_build_object('period', (
    select jsonb_build_object('from', min(enquiry_date), 'to', max(enquiry_date),
      'months', greatest(1, (extract(year from age(max(enquiry_date), min(enquiry_date))) * 12
                           + extract(month from age(max(enquiry_date), min(enquiry_date))))::int))
      from iberia.enquiries));

  -- Two win rates on purpose. By count answers "how often do we win"; by
  -- value answers "do we win the ones worth winning", and they can disagree
  -- sharply. Only decided rows are counted either way: treating everything
  -- still open as a loss reports a collapsing hit rate every time the desk
  -- gets busy, which is exactly backwards.
  j := j || jsonb_build_object('funnel', jsonb_build_object(
    'enquiries', n_all, 'won', won_n, 'won_eur', round(won_eur),
    'lost', lost_n, 'lost_eur', round(lost_eur),
    'open', open_n, 'open_eur', round(open_eur), 'decided', n_decided,
    'win_rate_count', case when n_decided > 0 then round(won_n::numeric / n_decided, 4) end,
    'win_rate_value', case when (won_eur + lost_eur) > 0
                      then round(won_eur / (won_eur + lost_eur), 4) end,
    'enough', n_decided >= 20));

  -- WHY THE SIZES ARE HERE
  -- The two win rates disagree on this register -- 38% by count, 17% by
  -- value -- and the obvious reading is "they win small jobs and lose large
  -- ones", which is a systemic finding somebody would act on. It is wrong.
  -- The MEDIAN won enquiry is larger than the median lost one; the value gap
  -- is one rejected enquiry of 1.375m against 1.988m of rejections in total.
  -- One deal, not a pattern.
  --
  -- A sheet carrying only the two rates invites exactly that wrong story, and
  -- a model has no way to find the outlier that would stop it. So the shape
  -- of the distribution goes in the sheet: medians beside means, the largest
  -- single loss, and what share of all lost value that one deal is.
  j := j || jsonb_build_object('deal_size', (
    select jsonb_build_object(
      'won_median', round(percentile_cont(0.5) within group (order by price_ex_vat)
                          filter (where status = 'Gautas PO')),
      'won_mean', round(avg(price_ex_vat) filter (where status = 'Gautas PO')),
      'won_max', round(max(price_ex_vat) filter (where status = 'Gautas PO')),
      'lost_median', round(percentile_cont(0.5) within group (order by price_ex_vat)
                           filter (where status = 'Atmesta užklausa')),
      'lost_mean', round(avg(price_ex_vat) filter (where status = 'Atmesta užklausa')),
      'lost_max', round(big_lost),
      'lost_max_share_of_lost', case when lost_eur > 0 then round(big_lost / lost_eur, 4) end,
      'open_median', round(percentile_cont(0.5) within group (order by price_ex_vat)
                           filter (where status = 'Vykdoma')))
      from iberia.enquiries where price_ex_vat is not null));

  -- Asked against won, per client. "Who buys" is half the question; the other
  -- half is who costs a lot of quoting and buys nothing.
  j := j || jsonb_build_object('clients', (
    select coalesce(jsonb_agg(x order by (x->>'won_eur')::numeric desc), '[]'::jsonb) from (
      select jsonb_build_object('client', client,
               'asked', count(*),
               'won', count(*) filter (where status = 'Gautas PO'),
               'won_eur', round(coalesce(sum(price_ex_vat) filter (where status = 'Gautas PO'), 0)),
               'lost_eur', round(coalesce(sum(price_ex_vat) filter (where status = 'Atmesta užklausa'), 0)),
               'share', case when won_eur > 0 then round(coalesce(sum(price_ex_vat)
                             filter (where status = 'Gautas PO'), 0) / won_eur, 4) end) as x
        from iberia.enquiries
       where coalesce(client, '') <> '' group by client
      having count(*) >= 3) s));

  -- Which supplier's quotes turn into orders. The company buys through these
  -- names, so a supplier whose quotes never win is either priced wrong or
  -- asked for the wrong things.
  j := j || jsonb_build_object('suppliers', (
    select coalesce(jsonb_agg(x order by (x->>'asked')::int desc), '[]'::jsonb) from (
      select jsonb_build_object('supplier', supplier, 'asked', count(*),
               'won', count(*) filter (where status = 'Gautas PO'),
               'won_eur', round(coalesce(sum(price_ex_vat) filter (where status = 'Gautas PO'), 0))) as x
        from iberia.enquiries
       where coalesce(supplier, '') <> '' group by supplier
      having count(*) >= 5) s));

  -- Recent against the run before it, so "is it getting better" has an
  -- answer that is not the reader eyeballing a bar chart.
  j := j || jsonb_build_object('trend', (
    select jsonb_build_object(
      'last_90d_enquiries', count(*) filter (where enquiry_date > today - 90),
      'last_90d_won', count(*) filter (where enquiry_date > today - 90 and status = 'Gautas PO'),
      'last_90d_won_eur', round(coalesce(sum(price_ex_vat)
          filter (where enquiry_date > today - 90 and status = 'Gautas PO'), 0)),
      'prev_90d_enquiries', count(*) filter (where enquiry_date <= today - 90 and enquiry_date > today - 180),
      'prev_90d_won', count(*) filter (where enquiry_date <= today - 90
          and enquiry_date > today - 180 and status = 'Gautas PO'),
      'prev_90d_won_eur', round(coalesce(sum(price_ex_vat)
          filter (where enquiry_date <= today - 90 and enquiry_date > today - 180
                  and status = 'Gautas PO'), 0)))
      from iberia.enquiries));

  -- Median, not mean. In a register kept by hand there is always one enquiry
  -- that sat for two years, and it drags an average far enough to be useless.
  j := j || jsonb_build_object('cycle', (
    select jsonb_build_object(
             'days_to_po', percentile_cont(0.5) within group (order by (po_date - enquiry_date)),
             'n', count(*), 'enough', count(*) >= 10)
      from iberia.enquiries
     where po_date is not null and enquiry_date is not null
       and po_date >= enquiry_date and po_date - enquiry_date < 3650));

  -- An enquiry with no quote sent has no price yet, so the value of that pile
  -- is not zero -- it is unknown, and those are not the same sentence. The
  -- euro figure here reported 0 against 23 rows on the live register, which
  -- reads as a broken sum rather than as "nobody has priced these".
  j := j || jsonb_build_object('stale', jsonb_build_object(
    'no_quote_over_14d', (select count(*) from iberia.enquiries
       where not coalesce(quoted_to_client, false) and status = 'Vykdoma' and enquiry_date < today - 14),
    'no_quote_over_14d_priced', (select count(*) from iberia.enquiries
       where not coalesce(quoted_to_client, false) and status = 'Vykdoma'
         and enquiry_date < today - 14 and coalesce(price_ex_vat, 0) > 0),
    'quoted_undecided_over_30d', (select count(*) from iberia.enquiries
       where coalesce(quoted_to_client, false) and status = 'Vykdoma' and enquiry_date < today - 30),
    'quoted_undecided_over_30d_eur', (select round(coalesce(sum(price_ex_vat), 0)) from iberia.enquiries
       where coalesce(quoted_to_client, false) and status = 'Vykdoma' and enquiry_date < today - 30),
    'quoted_undecided_over_90d', (select count(*) from iberia.enquiries
       where coalesce(quoted_to_client, false) and status = 'Vykdoma' and enquiry_date < today - 90)));

  j := j || jsonb_build_object('by_month', (
    select coalesce(jsonb_agg(jsonb_build_object('month', m, 'enquiries', n, 'won', w,
             'won_eur', e) order by m), '[]'::jsonb)
      from (select to_char(enquiry_date, 'YYYY-MM') as m, count(*) as n,
                   count(*) filter (where status = 'Gautas PO') as w,
                   round(coalesce(sum(price_ex_vat) filter (where status = 'Gautas PO'), 0)) as e
              from iberia.enquiries where enquiry_date is not null group by 1) s));

  -- One priced row out of two hundred is not a margin, it is an anecdote.
  -- Below the threshold the block says so and says what would fix it, and the
  -- model is told it may not reason about a block whose `enough` is false.
  j := j || jsonb_build_object('margin', (
    select jsonb_build_object('rows_with_cost', n_cost, 'rows_total', n_all,
             'coverage', case when n_all > 0 then round(n_cost::numeric / n_all, 4) end,
             'won_with_cost', count(*), 'sold_eur', round(coalesce(sum(price_ex_vat), 0)),
             'cost_eur', round(coalesce(sum(cost_ex_vat), 0)),
             'margin_pct', case when coalesce(sum(price_ex_vat), 0) > 0
                           then round((sum(price_ex_vat) - sum(cost_ex_vat)) / sum(price_ex_vat), 4) end,
             'enough', count(*) >= 15)
      from iberia.enquiries
     where status = 'Gautas PO' and cost_ex_vat is not null and price_ex_vat is not null));

  -- Where the money went, and what not knowing it costs. Both computed by
  -- the two helpers at the foot of this file.
  j := j || jsonb_build_object('money', iberia.advice_money());
  j := j || jsonb_build_object('unknown_profit', iberia.advice_unknown_profit());

  -- The block that earns its place on a register this young. Everything the
  -- model cannot say is downstream of these columns, so the sheet names them
  -- rather than leaving the reader to wonder why the advice is thin.
  j := j || jsonb_build_object('coverage', jsonb_build_object(
    'rows', n_all, 'missing_cost', n_all - n_cost,
    'missing_owner', (select count(*) from iberia.enquiries where coalesce(owner, '') = ''),
    'delivered_unpaid', (select count(*) from iberia.enquiries
                          where coalesce(delivered, false) and not coalesce(paid, false)),
    'delivered_unpaid_eur', (select round(coalesce(sum(price_ex_vat), 0)) from iberia.enquiries
                              where coalesce(delivered, false) and not coalesce(paid, false)),
    'people', (select count(*) from iberia.people),
    'overheads', (select count(*) from iberia.overheads),
    'projects', (select count(*) from iberia.projects)));

  -- Totals only, and only to an owner. sees_payroll() rather than
  -- sees_money(): this is the payroll gate everywhere else in the schema and
  -- a sum is still a payroll figure.
  if iberia.sees_payroll() then
    j := j || jsonb_build_object('burn', (
      select jsonb_build_object('headcount', b.headcount, 'payroll_month', round(b.payroll),
               'overheads_month', round(b.overheads), 'burn_month', round(b.burn),
               'enough', b.headcount >= 3) from iberia.company_burn() b));
  end if;

  j := j || jsonb_build_object('projects', (
    select jsonb_build_object('n', count(*), 'enough', count(*) >= 3) from iberia.projects));

  return j;
end $$;


--
-- Name: advice_money(); Type: FUNCTION; Schema: iberia; Owner: -
--

CREATE FUNCTION iberia.advice_money() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
-- WHERE THE MONEY WENT, WITHOUT REIMPLEMENTING A SINGLE FORMULA
--
-- The plan side of every sheet is computed -- hours times rate times one plus
-- the burden, quantity times unit price, and so on -- and those formulas live
-- in the browser, mirroring the Excel workbook the company used before.
-- Writing them again here would create a second implementation of the same
-- arithmetic, and two implementations of one formula are two answers as soon
-- as somebody edits one of them.
--
-- The ACTUAL side needs none of that. Every actual on every sheet is a number
-- a person typed. Summing typed numbers is not a formula, it is a sum -- so
-- "where did the money go" is answerable here exactly, while "how does that
-- compare to plan" stays where its arithmetic already lives.
with rows as (
  select p.id,
         k.sheet,
         sum(coalesce(nullif(e->>'actual','')::numeric, 0)) as actual
    from iberia.projects p
    cross join lateral (values ('revenue'),('labor'),('subs'),
                               ('travel'),('materials'),('logistics')) as k(sheet)
    cross join lateral jsonb_array_elements(
                 coalesce(p.data->k.sheet, '[]'::jsonb)) as e
   group by p.id, k.sheet
), tot as (
  select sheet, sum(actual) as actual from rows group by sheet
), direct as (
  select coalesce(sum(actual),0) as d from tot where sheet <> 'revenue'
)
select jsonb_build_object(
  'projects', (select count(*) from iberia.projects),
  'projects_with_actuals', (select count(distinct id) from rows where actual > 0),
  'revenue_actual',   (select coalesce(sum(actual),0) from tot where sheet='revenue'),
  'labor_actual',     (select coalesce(sum(actual),0) from tot where sheet='labor'),
  'subs_actual',      (select coalesce(sum(actual),0) from tot where sheet='subs'),
  'travel_actual',    (select coalesce(sum(actual),0) from tot where sheet='travel'),
  'materials_actual', (select coalesce(sum(actual),0) from tot where sheet='materials'),
  'logistics_actual', (select coalesce(sum(actual),0) from tot where sheet='logistics'),
  'direct_actual',    (select d from direct),
  -- what share of every euro spent went to each article; the answer to
  -- "where does the money go" in one line
  'share_of_spend', (
    select coalesce(jsonb_object_agg(sheet, round(actual / nullif((select d from direct),0), 4)), '{}'::jsonb)
      from tot where sheet <> 'revenue' and actual > 0),
  'enough', (select d from direct) > 0
) $$;


--
-- Name: advice_unknown_profit(); Type: FUNCTION; Schema: iberia; Owner: -
--

CREATE FUNCTION iberia.advice_unknown_profit() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
-- The prize for filling the cost column, in euros rather than in scolding.
-- "Fill in the cost" is a chore; "the profit on 408,352 EUR of work you have
-- already delivered is unknown" is a reason.
select jsonb_build_object(
  'won_no_cost',            count(*) filter (where status='Gautas PO' and cost_ex_vat is null),
  'won_no_cost_eur',        round(coalesce(sum(price_ex_vat) filter (where status='Gautas PO' and cost_ex_vat is null),0)),
  'delivered_no_cost',      count(*) filter (where status='Gautas PO' and delivered and cost_ex_vat is null),
  'delivered_no_cost_eur',  round(coalesce(sum(price_ex_vat) filter (where status='Gautas PO' and delivered and cost_ex_vat is null),0)),
  'enough', true)
from iberia.enquiries $$;


--
-- Name: check_act_fields(jsonb); Type: FUNCTION; Schema: iberia; Owner: -
--

CREATE FUNCTION iberia.check_act_fields(p_defs jsonb) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  part text;
  arr  jsonb;
  el   jsonb;
  seen text[] := '{}';
  cap  int;
begin
  if p_defs is null or jsonb_typeof(p_defs) <> 'object' then
    raise exception 'the field definition must be an object' using errcode = '22023';
  end if;

  foreach part in array array['header', 'columns'] loop
    arr := coalesce(p_defs -> part, '[]'::jsonb);
    if jsonb_typeof(arr) <> 'array' then
      raise exception '% must be a list', part using errcode = '22023';
    end if;

    -- Six either way now. Header fields print in a block with room to spare;
    -- columns past three turn the sheet landscape, and past six even
    -- landscape stops holding a description wide enough to describe work.
    cap := 6;
    if jsonb_array_length(arr) > cap then
      raise exception 'at most % extra %s -- more will not print', cap, part
        using errcode = '22023';
    end if;

    for el in select * from jsonb_array_elements(arr) loop
      if coalesce(el->>'key','') !~ '^[a-z][a-z0-9_]{0,23}$' then
        raise exception 'bad field key %', coalesce(el->>'key','(none)')
          using errcode = '22023';
      end if;
      if btrim(coalesce(el->>'label','')) = '' then
        raise exception 'field % has no label', el->>'key' using errcode = '22023';
      end if;
      if length(el->>'label') > 40 then
        raise exception 'the label for % is too long to print', el->>'key'
          using errcode = '22023';
      end if;
      if (el->>'key') = any(seen) then
        raise exception 'two fields share the key %', el->>'key' using errcode = '22023';
      end if;
      seen := seen || (el->>'key');
    end loop;
  end loop;
end $_$;




--
-- Name: acts; Type: TABLE; Schema: iberia; Owner: -
--

CREATE TABLE iberia.acts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    project_id uuid,
    number text DEFAULT ''::text NOT NULL,
    act_date date DEFAULT CURRENT_DATE NOT NULL,
    customer text DEFAULT ''::text NOT NULL,
    imo text DEFAULT ''::text NOT NULL,
    object text DEFAULT ''::text NOT NULL,
    project_ref text DEFAULT ''::text NOT NULL,
    lines jsonb DEFAULT '[]'::jsonb NOT NULL,
    rep_name text DEFAULT ''::text NOT NULL,
    note text,
    rev bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid DEFAULT iberia.admin_uid(),
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid DEFAULT iberia.admin_uid(),
    signature text,
    signed_at timestamp with time zone,
    signed_by uuid,
    sign_log jsonb DEFAULT '[]'::jsonb NOT NULL,
    extra jsonb DEFAULT '{}'::jsonb NOT NULL,
    field_defs jsonb,
    exec_signature text,
    exec_name text,
    exec_signed_at timestamp with time zone,
    exec_signed_by uuid,
    CONSTRAINT acts_exec_signature_chk CHECK (((exec_signature IS NULL) OR ((exec_signature ~~ 'data:image/png;base64,%'::text) AND ((length(exec_signature) >= 100) AND (length(exec_signature) <= 400000))))),
    CONSTRAINT acts_signature_chk CHECK (((signature IS NULL) OR ((signature ~~ 'data:image/png;base64,%'::text) AND ((length(signature) >= 100) AND (length(signature) <= 400000)))))
);


--
-- Name: acts_v; Type: VIEW; Schema: iberia; Owner: -
--

CREATE VIEW iberia.acts_v AS
 SELECT a.id,
    a.project_id,
    a.number,
    a.act_date,
    a.customer,
    a.imo,
    a.object,
    a.project_ref,
    a.lines,
    a.rep_name,
    a.note,
    a.extra,
    a.field_defs,
    (( SELECT count(*) AS count
           FROM jsonb_array_elements(a.lines) l(value)
          WHERE (COALESCE((l.value ->> 'work'::text), ''::text) <> ''::text)))::integer AS line_count,
    a.signature,
    (a.signature IS NOT NULL) AS signed,
    a.signed_at,
    a.sign_log,
    NULLIF(COALESCE(NULLIF(sp.name, ''::text), NULLIF(sp.email, ''::text)), ''::text) AS witnessed_by,
    a.exec_signature,
    (a.exec_signature IS NOT NULL) AS exec_signed,
    a.exec_name,
    a.exec_signed_at,
    NULLIF(COALESCE(NULLIF(xp.name, ''::text), NULLIF(xp.email, ''::text)), ''::text) AS executed_by,
    NULLIF(COALESCE(NULLIF(pr.name, ''::text), NULLIF(pr.email, ''::text)), ''::text) AS written_by,
    a.rev,
    a.created_at,
    a.updated_at
   FROM (((iberia.acts a
     LEFT JOIN public.profiles pr ON ((pr.id = a.created_by)))
     LEFT JOIN public.profiles sp ON ((sp.id = a.signed_by)))
     LEFT JOIN public.profiles xp ON ((xp.id = a.exec_signed_by)))
  WHERE (iberia.admin_uid() IS NOT NULL);


--
-- Name: clear_act_exec(uuid, bigint); Type: FUNCTION; Schema: iberia; Owner: -
--

CREATE FUNCTION iberia.clear_act_exec(p_id uuid, p_rev bigint) RETURNS SETOF iberia.acts_v
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare cur iberia.acts%rowtype; who text;
begin
  if iberia.admin_uid() is null then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  select * into cur from iberia.acts where id = p_id;
  if not found then return; end if;
  if p_rev is not null and cur.rev <> p_rev then return; end if;
  if cur.exec_signature is null then
    return query select * from iberia.acts_v where id = p_id; return;
  end if;

  select coalesce(nullif(name,''), nullif(email,'')) into who
    from public.profiles where id = iberia.admin_uid();

  update iberia.acts set
    exec_signature = null, exec_name = null,
    exec_signed_at = null, exec_signed_by = null,
    sign_log = sign_log || jsonb_build_object(
                 'at', to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
                 'action', 'executor cleared',
                 'witness', who,
                 'rep', cur.exec_name),
    rev = rev + 1, updated_at = now(), updated_by = iberia.admin_uid()
  where id = p_id;

  return query select * from iberia.acts_v where id = p_id;
end $$;


--
-- Name: company_burn(date); Type: FUNCTION; Schema: iberia; Owner: -
--

CREATE FUNCTION iberia.company_burn(p_on date DEFAULT CURRENT_DATE) RETURNS TABLE(headcount integer, payroll numeric, overheads numeric, burn numeric, hour_cost_avg numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  -- No rows rather than zeroes. Written first as a set of `where
  -- sees_payroll()` subqueries, it returned headcount 0, payroll 0, burn 0 to
  -- a manager -- which does not read as "you may not see this", it reads as
  -- "the company spends nothing", and it would have been believed. An empty
  -- result the app renders as a dash; a zero it renders as a fact.
  if not iberia.sees_payroll() then
    return;
  end if;

  return query
  with staff as (
    select p.monthly_cost, p.hours_month from iberia.people p
     where (p.start_date is null or p.start_date <= p_on)
       and (p.end_date   is null or p.end_date   >= p_on)
  ), fixed as (
    select o.amount_month from iberia.overheads o
     where (o.start_date is null or o.start_date <= p_on)
       and (o.end_date   is null or o.end_date   >= p_on)
  )
  select
    (select count(*)::int from staff),
    (select coalesce(sum(monthly_cost), 0) from staff),
    (select coalesce(sum(amount_month), 0) from fixed),
    (select coalesce(sum(monthly_cost), 0) from staff)
      + (select coalesce(sum(amount_month), 0) from fixed),
    (select round(avg(monthly_cost / nullif(hours_month, 0)), 2) from staff);
end $$;


--
-- Name: company_track(); Type: FUNCTION; Schema: iberia; Owner: -
--

CREATE FUNCTION iberia.company_track() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  ent text := case tg_table_name when 'people' then 'person' else 'overhead' end;
  lbl text := coalesce(new.name, old.name);
  f   text;
  a   text;
  b   text;
begin
  if tg_op = 'INSERT' then
    insert into iberia.company_history (entity, row_id, label, field, was, now)
    values (ent, new.id, lbl, 'created', null, lbl);
    return new;
  end if;

  foreach f in array (case when ent = 'person'
    then array['name','job_title','department','contract','gross_salary',
               'monthly_cost','hours_month','start_date','end_date']
    else array['name','category','amount_month','start_date','end_date'] end)
  loop
    a := to_jsonb(old) ->> f;
    b := to_jsonb(new) ->> f;
    if a is distinct from b then
      insert into iberia.company_history (entity, row_id, label, field, was, now)
      values (ent, new.id, lbl, f, a, b);
    end if;
  end loop;
  return new;
end $$;


--
-- Name: create_act(jsonb); Type: FUNCTION; Schema: iberia; Owner: -
--

CREATE FUNCTION iberia.create_act(p_row jsonb) RETURNS SETOF iberia.acts_v
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  new_id uuid; v_pid uuid := nullif(p_row->>'project_id','')::uuid;
  v_num text; i int;
begin
  if iberia.admin_uid() is null then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  v_num := iberia.next_act_number(v_pid, coalesce(p_row->>'number',''));
  for i in 1..5 loop
    begin
      insert into iberia.acts (project_id, number, act_date, customer, imo, object,
                               project_ref, lines, rep_name, note, extra)
      values (v_pid, v_num,
              coalesce(nullif(p_row->>'act_date','')::date, current_date),
              coalesce(p_row->>'customer',''), coalesce(p_row->>'imo',''),
              coalesce(p_row->>'object',''), coalesce(p_row->>'project_ref',''),
              coalesce(p_row->'lines', '[]'::jsonb),
              coalesce(p_row->>'rep_name',''), p_row->>'note',
              coalesce(p_row->'extra', '{}'::jsonb))
      returning id into new_id;
      exit;
    exception when unique_violation then
      v_num := iberia.next_act_number(v_pid, v_num);
      if i = 5 then raise; end if;
    end;
  end loop;
  return query select * from iberia.acts_v where id = new_id;
end $$;


