--
-- Name: documents_v; Type: VIEW; Schema: iberia; Owner: -
--

CREATE VIEW iberia.documents_v AS
 SELECT d.id,
    d.path,
    d.filename,
    d.mime,
    d.size_bytes,
    d.kind,
    d.doc_date,
    d.ref,
    d.amount,
    d.counterparty,
    d.valid_until,
    d.note,
        CASE
            WHEN (d.valid_until IS NULL) THEN NULL::integer
            ELSE (d.valid_until - CURRENT_DATE)
        END AS days_left,
    d.project_id,
    d.enquiry_id,
    p.project_id AS project_ref,
    e.number AS enquiry_ref,
    d.created_by,
    NULLIF(COALESCE(NULLIF(pr.name, ''::text), NULLIF(pr.email, ''::text)), ''::text) AS uploaded_by,
    d.rev,
    d.created_at,
    d.updated_at
   FROM (((iberia.documents d
     LEFT JOIN iberia.projects p ON ((p.id = d.project_id)))
     LEFT JOIN iberia.enquiries e ON ((e.id = d.enquiry_id)))
     LEFT JOIN public.profiles pr ON ((pr.id = d.created_by)))
  WHERE (iberia.sees_money() AND ((d.project_id IS NOT NULL) OR (iberia.my_role() = 'admin'::text)));


--
-- Name: create_document(jsonb); Type: FUNCTION; Schema: iberia; Owner: -
--

CREATE FUNCTION iberia.create_document(p_row jsonb) RETURNS SETOF iberia.documents_v
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare new_id uuid;
begin
  if not iberia.sees_money() then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  insert into iberia.documents (path, filename, mime, size_bytes, kind,
                                doc_date, ref, amount, counterparty, valid_until,
                                note, project_id, enquiry_id)
  values (p_row->>'path', coalesce(p_row->>'filename', 'file'),
          p_row->>'mime', nullif(p_row->>'size_bytes','')::bigint,
          coalesce(p_row->>'kind', 'other'),
          nullif(p_row->>'doc_date','')::date,
          p_row->>'ref',
          nullif(p_row->>'amount','')::numeric,
          p_row->>'counterparty',
          nullif(p_row->>'valid_until','')::date,
          p_row->>'note',
          nullif(p_row->>'project_id','')::uuid,
          nullif(p_row->>'enquiry_id','')::uuid)
  returning id into new_id;
  return query select * from iberia.documents_v where id = new_id;
end $$;


--
-- Name: enquiry_days_unquoted(boolean, date, text); Type: FUNCTION; Schema: iberia; Owner: -
--

CREATE FUNCTION iberia.enquiry_days_unquoted(p_quoted boolean, p_date date, p_status text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when p_quoted or p_date is null then 0
    else greatest(0, (current_date - p_date))::integer
  end
$$;


--
-- Name: enquiries_v; Type: VIEW; Schema: iberia; Owner: -
--

CREATE VIEW iberia.enquiries_v AS
 SELECT id,
    number,
    client,
    description,
    enquiry_date,
    sent_to_supplier,
    supplier,
    quoted_to_client,
    iberia.enquiry_days_unquoted(quoted_to_client, enquiry_date, status) AS days_unquoted,
    status,
    po_date,
    cost_ex_vat,
    price_ex_vat,
        CASE
            WHEN (cost_ex_vat IS NULL) THEN NULL::numeric
            ELSE (price_ex_vat - cost_ex_vat)
        END AS margin_eur,
        CASE
            WHEN ((cost_ex_vat IS NULL) OR (price_ex_vat = (0)::numeric)) THEN NULL::numeric
            ELSE round(((price_ex_vat - cost_ex_vat) / price_ex_vat), 4)
        END AS margin_pct,
    delivered,
    paid,
    paid_date,
    invoice_no,
    owner,
    note,
    rev,
    created_at,
    updated_at,
    updated_by
   FROM iberia.enquiries e
  WHERE iberia.sees_money();


--
-- Name: create_enquiry(jsonb); Type: FUNCTION; Schema: iberia; Owner: -
--

CREATE FUNCTION iberia.create_enquiry(p_row jsonb) RETURNS SETOF iberia.enquiries_v
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare new_id uuid;
begin
  if not iberia.sees_money() then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  insert into iberia.enquiries (number, client, description, enquiry_date,
      sent_to_supplier, supplier, quoted_to_client, status, po_date,
      cost_ex_vat, price_ex_vat, delivered, paid, paid_date, invoice_no, owner, note)
  values (coalesce(nullif(p_row->>'number',''), 'NEW'),
      p_row->>'client', p_row->>'description', nullif(p_row->>'enquiry_date','')::date,
      coalesce((p_row->>'sent_to_supplier')::boolean, false), p_row->>'supplier',
      coalesce((p_row->>'quoted_to_client')::boolean, false),
      coalesce(nullif(p_row->>'status',''), 'Vykdoma'), nullif(p_row->>'po_date','')::date,
      nullif(p_row->>'cost_ex_vat','')::numeric,
      coalesce((p_row->>'price_ex_vat')::numeric, 0),
      coalesce((p_row->>'delivered')::boolean, false),
      coalesce((p_row->>'paid')::boolean, false),
      nullif(p_row->>'paid_date','')::date, p_row->>'invoice_no',
      p_row->>'owner', p_row->>'note')
  returning id into new_id;
  return query select * from iberia.enquiries_v where id = new_id;
end $$;


