--
-- Name: people; Type: TABLE; Schema: iberia; Owner: -
--

CREATE TABLE iberia.people (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    job_title text DEFAULT ''::text NOT NULL,
    department text DEFAULT ''::text NOT NULL,
    monthly_cost numeric(12,2) DEFAULT 0 NOT NULL,
    hours_month numeric(6,1) DEFAULT 130 NOT NULL,
    start_date date,
    end_date date,
    note text,
    rev bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid DEFAULT iberia.admin_uid(),
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid DEFAULT iberia.admin_uid(),
    gross_salary numeric(12,2),
    contract text DEFAULT 'permanent'::text NOT NULL,
    CONSTRAINT people_contract_chk CHECK ((contract = ANY (ARRAY['permanent'::text, 'fixed'::text])))
);


--
-- Name: people_v; Type: VIEW; Schema: iberia; Owner: -
--

CREATE VIEW iberia.people_v AS
 SELECT id,
    name,
    job_title,
    department,
    contract,
    gross_salary,
    round((COALESCE(gross_salary, (0)::numeric) * iberia.employer_rate(contract)), 2) AS employer_cost,
    monthly_cost,
    hours_month,
        CASE
            WHEN (hours_month > (0)::numeric) THEN round((monthly_cost / hours_month), 2)
            ELSE NULL::numeric
        END AS hour_cost,
    start_date,
    end_date,
    ((end_date IS NULL) OR (end_date >= CURRENT_DATE)) AS active,
    note,
    rev,
    created_at,
    updated_at,
    updated_by
   FROM iberia.people p
  WHERE iberia.sees_payroll();


--
-- Name: create_person(jsonb); Type: FUNCTION; Schema: iberia; Owner: -
--

CREATE FUNCTION iberia.create_person(p_row jsonb) RETURNS SETOF iberia.people_v
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  new_id uuid;
  g numeric;
  c text;
begin
  if not iberia.sees_payroll() then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  g := coalesce((p_row->>'gross_salary')::numeric, 0);
  c := case when p_row->>'contract' = 'fixed' then 'fixed' else 'permanent' end;

  insert into iberia.people (name, job_title, department, contract, gross_salary,
                             monthly_cost, hours_month, start_date, end_date, note)
  values (coalesce(p_row->>'name', ''), coalesce(p_row->>'job_title', ''),
          coalesce(p_row->>'department', ''), c, g,
          round(g * (1 + iberia.employer_rate(c)), 2),
          coalesce((p_row->>'hours_month')::numeric, 130),
          nullif(p_row->>'start_date', '')::date,
          nullif(p_row->>'end_date', '')::date,
          p_row->>'note')
  returning id into new_id;
  return query select * from iberia.people_v where id = new_id;
end $$;


--
-- Name: strip_money(jsonb); Type: FUNCTION; Schema: iberia; Owner: -
--

CREATE FUNCTION iberia.strip_money(d jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  out_d jsonb := coalesce(d, '{}'::jsonb);
begin
  out_d := out_d - 'revenue';
  out_d := out_d #- '{card,contract}';
  out_d := out_d #- '{card,advance}';
  out_d := out_d #- '{settings,targetMargin}';

  if jsonb_typeof(out_d->'materials') = 'array' then
    out_d := jsonb_set(out_d, '{materials}', coalesce((
      select jsonb_agg(row_x - 'rebill' - 'rebillAmt' order by ord)
        from jsonb_array_elements(out_d->'materials') with ordinality as t(row_x, ord)
    ), '[]'::jsonb));
  end if;

  if jsonb_typeof(out_d->'logistics') = 'array' then
    out_d := jsonb_set(out_d, '{logistics}', coalesce((
      select jsonb_agg(row_x - 'rebill' - 'recoverable' order by ord)
        from jsonb_array_elements(out_d->'logistics') with ordinality as t(row_x, ord)
    ), '[]'::jsonb));
  end if;

  return out_d;
end $$;


--
-- Name: projects_v; Type: VIEW; Schema: iberia; Owner: -
--

CREATE VIEW iberia.projects_v AS
 SELECT id,
        CASE
            WHEN iberia.sees_money() THEN data
            ELSE iberia.strip_money(data)
        END AS data,
    project_id,
    client,
    site,
    pm,
    start_date,
    end_date,
    currency,
    locked,
    rev,
    created_at,
    created_by,
    updated_at,
    updated_by,
    iberia.sees_money() AS money
   FROM iberia.projects p
  WHERE (iberia.admin_uid() IS NOT NULL);


--
-- Name: create_project(jsonb); Type: FUNCTION; Schema: iberia; Owner: -
--

CREATE FUNCTION iberia.create_project(p_data jsonb) RETURNS SETOF iberia.projects_v
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare new_id uuid;
begin
  if auth.uid() is not null and not iberia.sees_money() then
    raise exception 'Only a manager can create a project.' using errcode = 'insufficient_privilege';
  end if;
  insert into iberia.projects (data) values (coalesce(p_data, '{}'::jsonb)) returning id into new_id;
  return query select * from iberia.projects_v where id = new_id;
end $$;


