--
-- Name: create_signature(text, text); Type: FUNCTION; Schema: iberia; Owner: -
--

CREATE FUNCTION iberia.create_signature(p_label text, p_image text) RETURNS SETOF iberia.signatures_v
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare new_id uuid;
begin
  if iberia.admin_uid() is null then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  if p_image is null or p_image !~ '^data:image/png;base64,' then
    raise exception 'not a signature' using errcode = '22023';
  end if;
  if length(p_image) > 400000 then
    raise exception 'signature too large' using errcode = '22023';
  end if;
  if btrim(coalesce(p_label, '')) = '' then
    raise exception 'a signature needs a name under it' using errcode = '22023';
  end if;
  -- Six is more than anybody needs and few enough to pick from at a glance.
  if (select count(*) from iberia.signatures where owner = iberia.admin_uid()) >= 6 then
    raise exception 'six signatures is the limit' using errcode = '22023';
  end if;

  insert into iberia.signatures (owner, label, image)
  values (iberia.admin_uid(), btrim(p_label), p_image)
  returning id into new_id;
  return query select * from iberia.signatures_v where id = new_id;
end $$;


