  end if;
  delete from iberia.acts where id = p_id;
end $$;


--
-- Name: delete_document(uuid); Type: FUNCTION; Schema: iberia; Owner: -
--

CREATE FUNCTION iberia.delete_document(p_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare gone text; pid uuid;
begin
  select path, project_id into gone, pid from iberia.documents where id = p_id;
  if not found then return null; end if;

  -- An owner anywhere. Anyone else who may see money, on a job's file only.
  if iberia.my_role() <> 'admin'
     and not (iberia.sees_money() and pid is not null) then
    raise exception 'not permitted' using errcode = '42501';
  end if;

  delete from iberia.documents where id = p_id;
  return gone;
end $$;


