   where iberia.sees_money()
   group by d.kind
   order by count(*) desc;
$$;


--
-- Name: enquiry_track(); Type: FUNCTION; Schema: iberia; Owner: -
--

CREATE FUNCTION iberia.enquiry_track() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  f text;
  o text;
  n text;
begin
  -- the fields worth a line in a log: money, status, and the two flags that a
  -- single click can flip
  foreach f in array array['number','client','description','enquiry_date','supplier',
                           'sent_to_supplier','quoted_to_client','status','po_date',
                           'cost_ex_vat','price_ex_vat','delivered','paid','paid_date',
                           'invoice_no','owner']
  loop
    execute format('select ($1).%I::text, ($2).%I::text', f, f)
      into o, n using old, new;
    if o is distinct from n then
      insert into iberia.enquiry_history (enquiry_id, by_user, field, was, now_is)
      values (new.id, iberia.admin_uid(), f, o, n);
    end if;
  end loop;
  return new;
end $_$;


--
-- Name: guard_locked_project(); Type: FUNCTION; Schema: iberia; Owner: -
--

CREATE FUNCTION iberia.guard_locked_project() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if old.locked and coalesce((new.data->>'locked')::boolean, false) then
    raise exception 'Project % is closed. Reopen it before editing.', old.project_id
      using errcode = 'check_violation';
  end if;
  return new;
end $$;


--
-- Name: guard_signed_acts(); Type: FUNCTION; Schema: iberia; Owner: -
--

CREATE FUNCTION iberia.guard_signed_acts() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  n    int;
  nums text;
begin
  select count(*), string_agg(number, ', ' order by number)
    into n, nums
    from iberia.acts
   where project_id = old.id and signature is not null;

  if n > 0 then
    raise exception
      'This job has % signed act(s) on it (%). A signed act is a document, and deleting the job would take it. Clear the signature first if it really has to go.',
      n, nums
      using errcode = 'foreign_key_violation';
  end if;
  return old;
end $$;


--
-- Name: next_act_number(uuid, text); Type: FUNCTION; Schema: iberia; Owner: -
--

CREATE FUNCTION iberia.next_act_number(p_project uuid, p_wanted text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  stem text;
  n    int := 1;
  try  text;
begin
  if coalesce(p_wanted, '') = '' then return ''; end if;
  if not exists (select 1 from iberia.acts
                  where project_id is not distinct from p_project
                    and number = p_wanted) then
    return p_wanted;
  end if;

  stem := regexp_replace(p_wanted, '/[0-9]+$', '');
  loop
    try := stem || '/' || lpad(n::text, 2, '0');
    exit when not exists (select 1 from iberia.acts
                           where project_id is not distinct from p_project
                             and number = try);
    n := n + 1;
    -- A job with a thousand acts is not a numbering problem any more. Rather
    -- than spin, hand back something unmistakably unique and let a human see
    -- it and ask what happened.
    if n > 999 then
      return p_wanted || '-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 4);
    end if;
  end loop;
  return try;
end $_$;


--
-- Name: record_project_history(); Type: FUNCTION; Schema: iberia; Owner: -
--

CREATE FUNCTION iberia.record_project_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  insert into iberia.project_history (project, rev, data, changed_by)
  values (new.id, new.rev, new.data, iberia.admin_uid());

  delete from iberia.project_history
   where project = new.id
     and id not in (
       select id from iberia.project_history
        where project = new.id
        order by rev desc
        limit 50
     );
  return null;
end $$;


--
-- Name: restore_rebills(jsonb, jsonb, text, text[]); Type: FUNCTION; Schema: iberia; Owner: -
--

CREATE FUNCTION iberia.restore_rebills(incoming jsonb, stored jsonb, sheet text, keys text[]) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  merged jsonb;
begin
  if jsonb_typeof(incoming->sheet) <> 'array' then return incoming; end if;
  select jsonb_agg(
           case when jsonb_typeof(stored->sheet->(ord::int - 1)) = 'object'
                then row_x || (select coalesce(jsonb_object_agg(k, stored->sheet->(ord::int - 1)->k), '{}'::jsonb)
                                 from unnest(keys) k
                                where stored->sheet->(ord::int - 1) ? k)
                else row_x end
           order by ord)
    into merged
    from jsonb_array_elements(incoming->sheet) with ordinality as t(row_x, ord);
  return jsonb_set(incoming, array[sheet], coalesce(merged, '[]'::jsonb));
end $$;


--
-- Name: save_act(uuid, bigint, jsonb); Type: FUNCTION; Schema: iberia; Owner: -
--

CREATE FUNCTION iberia.save_act(p_id uuid, p_rev bigint, p_row jsonb) RETURNS SETOF iberia.acts_v
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare cur iberia.acts%rowtype;
begin
  if iberia.admin_uid() is null then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  select * into cur from iberia.acts where id = p_id;
  if not found then return; end if;
  if p_rev is not null and cur.rev <> p_rev then return; end if;
  if cur.signature is not null then
    raise exception 'act is signed' using errcode = '42501';
  end if;
  begin
    update iberia.acts set
      number      = coalesce(p_row->>'number', number),
      act_date    = coalesce(nullif(p_row->>'act_date','')::date, act_date),
      customer    = coalesce(p_row->>'customer', customer),
      imo         = coalesce(p_row->>'imo', imo),
      object      = coalesce(p_row->>'object', object),
      project_ref = coalesce(p_row->>'project_ref', project_ref),
      lines       = coalesce(p_row->'lines', lines),
      rep_name    = coalesce(p_row->>'rep_name', rep_name),
      note        = p_row->>'note',
      extra       = coalesce(p_row->'extra', extra),
      rev = rev + 1, updated_at = now(), updated_by = iberia.admin_uid()
    where id = p_id;
  exception when unique_violation then
    raise exception 'act number already used on this job' using errcode = '23505';
  end;
  return query select * from iberia.acts_v where id = p_id;
end $$;


--
-- Name: act_fields; Type: TABLE; Schema: iberia; Owner: -
--

CREATE TABLE iberia.act_fields (
    only_row boolean DEFAULT true NOT NULL,
    defs jsonb DEFAULT '{"header": [], "columns": []}'::jsonb NOT NULL,
    rev bigint DEFAULT 1 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid DEFAULT iberia.admin_uid(),
    CONSTRAINT act_fields_only_row_check CHECK (only_row)
);


--
-- Name: act_fields_v; Type: VIEW; Schema: iberia; Owner: -
--

CREATE VIEW iberia.act_fields_v AS
 SELECT f.defs,
    f.rev,
    f.updated_at,
    NULLIF(COALESCE(NULLIF(pr.name, ''::text), NULLIF(pr.email, ''::text)), ''::text) AS updated_by
   FROM (iberia.act_fields f
     LEFT JOIN public.profiles pr ON ((pr.id = f.updated_by)))
  WHERE (iberia.admin_uid() IS NOT NULL);


--
-- Name: save_act_fields(bigint, jsonb); Type: FUNCTION; Schema: iberia; Owner: -
--

CREATE FUNCTION iberia.save_act_fields(p_rev bigint, p_defs jsonb) RETURNS SETOF iberia.act_fields_v
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare cur iberia.act_fields%rowtype;
begin
  if iberia.my_role() <> 'admin' then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  perform iberia.check_act_fields(p_defs);

  select * into cur from iberia.act_fields where only_row;
  if p_rev is not null and cur.rev <> p_rev then return; end if;

  update iberia.act_fields
     set defs = p_defs, rev = rev + 1, updated_at = now(), updated_by = iberia.admin_uid()
   where only_row;

  return query select * from iberia.act_fields_v;
end $$;


--
-- Name: save_document(uuid, bigint, jsonb); Type: FUNCTION; Schema: iberia; Owner: -
--

CREATE FUNCTION iberia.save_document(p_id uuid, p_rev bigint, p_row jsonb) RETURNS SETOF iberia.documents_v
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare cur iberia.documents%rowtype;
begin
  if not iberia.sees_money() then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  select * into cur from iberia.documents where id = p_id;
  if not found then return; end if;
  if p_rev is not null and cur.rev <> p_rev then return; end if;

  -- A manager may edit a job's file and must not be able to move it out of
  -- that job, or off it entirely: clearing project_id would push the document
  -- into the company's store, which is the one place they cannot see.
  if iberia.my_role() <> 'admin'
     and cur.project_id is distinct from nullif(p_row->>'project_id','')::uuid then
    raise exception 'not permitted' using errcode = '42501';
  end if;

  update iberia.documents set
    kind         = coalesce(p_row->>'kind', kind),
    doc_date     = nullif(p_row->>'doc_date','')::date,
    ref          = p_row->>'ref',
    amount       = nullif(p_row->>'amount','')::numeric,
    counterparty = p_row->>'counterparty',
    valid_until  = nullif(p_row->>'valid_until','')::date,
    note         = p_row->>'note',
    project_id   = nullif(p_row->>'project_id','')::uuid,
    enquiry_id   = nullif(p_row->>'enquiry_id','')::uuid,
    rev = rev + 1, updated_at = now(), updated_by = iberia.admin_uid()
  where id = p_id;

  return query select * from iberia.documents_v where id = p_id;
end $$;


--
-- Name: save_enquiry(uuid, bigint, jsonb); Type: FUNCTION; Schema: iberia; Owner: -
--

CREATE FUNCTION iberia.save_enquiry(p_id uuid, p_rev bigint, p_row jsonb) RETURNS SETOF iberia.enquiries_v
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare cur iberia.enquiries%rowtype;
begin
  if not iberia.sees_money() then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  select * into cur from iberia.enquiries where id = p_id;
  if not found then return; end if;
  -- a null revision is a deliberate overwrite, as it is for a project
  if p_rev is not null and cur.rev <> p_rev then return; end if;

  update iberia.enquiries set
    number = coalesce(p_row->>'number', number),
    client = p_row->>'client',
    description = p_row->>'description',
    enquiry_date = nullif(p_row->>'enquiry_date','')::date,
    sent_to_supplier = coalesce((p_row->>'sent_to_supplier')::boolean, false),
    supplier = p_row->>'supplier',
    quoted_to_client = coalesce((p_row->>'quoted_to_client')::boolean, false),
    status = coalesce(p_row->>'status', status),
    po_date = nullif(p_row->>'po_date','')::date,
    -- nullif before the cast: an empty box stays "not known" rather than
    -- becoming a cost of zero and inventing a 100% margin
    cost_ex_vat = nullif(p_row->>'cost_ex_vat','')::numeric,
    price_ex_vat = coalesce((p_row->>'price_ex_vat')::numeric, 0),
    delivered = coalesce((p_row->>'delivered')::boolean, false),
    paid = coalesce((p_row->>'paid')::boolean, false),
    paid_date = nullif(p_row->>'paid_date','')::date,
    invoice_no = p_row->>'invoice_no',
    owner = p_row->>'owner',
    note = p_row->>'note',
    rev = rev + 1,
    updated_at = now(),
    updated_by = iberia.admin_uid()
  where id = p_id;

  return query select * from iberia.enquiries_v where id = p_id;
end $$;


--
-- Name: save_overhead(uuid, bigint, jsonb); Type: FUNCTION; Schema: iberia; Owner: -
--

CREATE FUNCTION iberia.save_overhead(p_id uuid, p_rev bigint, p_row jsonb) RETURNS SETOF iberia.overheads_v
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare cur iberia.overheads%rowtype;
begin
  if not iberia.sees_money() then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  select * into cur from iberia.overheads where id = p_id;
  if not found then return; end if;
  if p_rev is not null and cur.rev <> p_rev then return; end if;

  update iberia.overheads set
    name         = coalesce(p_row->>'name', name),
    category     = coalesce(p_row->>'category', 'other'),
    amount_month = coalesce((p_row->>'amount_month')::numeric, 0),
    start_date   = nullif(p_row->>'start_date', '')::date,
    end_date     = nullif(p_row->>'end_date', '')::date,
    note         = p_row->>'note',
    rev = rev + 1, updated_at = now(), updated_by = iberia.admin_uid()
  where id = p_id;

  return query select * from iberia.overheads_v where id = p_id;
end $$;


--
-- Name: save_person(uuid, bigint, jsonb); Type: FUNCTION; Schema: iberia; Owner: -
--

CREATE FUNCTION iberia.save_person(p_id uuid, p_rev bigint, p_row jsonb) RETURNS SETOF iberia.people_v
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  cur iberia.people%rowtype;
  g   numeric;
  c   text;
begin
  if not iberia.sees_payroll() then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  select * into cur from iberia.people where id = p_id;
  if not found then return; end if;
  if p_rev is not null and cur.rev <> p_rev then return; end if;

  g := coalesce((p_row->>'gross_salary')::numeric, 0);
  c := case when p_row->>'contract' = 'fixed' then 'fixed' else 'permanent' end;

  update iberia.people set
    name         = coalesce(p_row->>'name', name),
    job_title    = coalesce(p_row->>'job_title', ''),
    department   = coalesce(p_row->>'department', ''),
    contract     = c,
    gross_salary = g,
    monthly_cost = round(g * (1 + iberia.employer_rate(c)), 2),
    hours_month  = coalesce((p_row->>'hours_month')::numeric, 130),
    start_date   = nullif(p_row->>'start_date', '')::date,
    end_date     = nullif(p_row->>'end_date', '')::date,
    note         = p_row->>'note',
    rev = rev + 1, updated_at = now(), updated_by = iberia.admin_uid()
  where id = p_id;

  return query select * from iberia.people_v where id = p_id;
end $$;


--
-- Name: save_project(uuid, bigint, jsonb); Type: FUNCTION; Schema: iberia; Owner: -
--

CREATE FUNCTION iberia.save_project(p_id uuid, p_rev bigint, p_data jsonb) RETURNS SETOF iberia.projects_v
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  cur iberia.projects%rowtype;
  merged jsonb;
begin
  select * into cur from iberia.projects where id = p_id;
  if not found then return; end if;
  -- a null revision is the deliberate overwrite the conflict dialog offers
  if p_rev is not null and cur.rev <> p_rev then return; end if;   -- somebody saved first
  if cur.locked and coalesce((p_data->>'locked')::boolean, false) then
    raise exception 'Project % is closed. Reopen it before editing.', cur.project_id
      using errcode = 'check_violation';
  end if;

  if iberia.sees_money() then
    merged := p_data;
  else
    -- keep every money key exactly as stored, take the rest from the client
    merged := iberia.strip_money(p_data);
    merged := merged || jsonb_build_object('revenue', coalesce(cur.data->'revenue', '[]'::jsonb));
    merged := jsonb_set(merged, '{card,contract}', coalesce(cur.data->'card'->'contract', 'null'::jsonb), true);
    merged := jsonb_set(merged, '{card,advance}',  coalesce(cur.data->'card'->'advance',  'null'::jsonb), true);
    merged := jsonb_set(merged, '{settings,targetMargin}',
                        coalesce(cur.data->'settings'->'targetMargin', 'null'::jsonb), true);
    -- rebill figures are per row, so they are put back by position
    merged := iberia.restore_rebills(merged, cur.data, 'materials', array['rebill', 'rebillAmt']);
    merged := iberia.restore_rebills(merged, cur.data, 'logistics', array['rebill', 'recoverable']);
  end if;

  update iberia.projects set data = merged where id = p_id;
  return query select * from iberia.projects_v where id = p_id;
end $$;


--
-- Name: sees_company(); Type: FUNCTION; Schema: iberia; Owner: -
--

CREATE FUNCTION iberia.sees_company() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$ select iberia.my_role() = 'admin' $$;


--
-- Name: sign_act(uuid, bigint, text, text, timestamp with time zone); Type: FUNCTION; Schema: iberia; Owner: -
--

CREATE FUNCTION iberia.sign_act(p_id uuid, p_rev bigint, p_signature text, p_rep_name text, p_signed_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS SETOF iberia.acts_v
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  cur iberia.acts%rowtype; who text; v_at timestamptz;
  v_claim text := 'device'; v_defs jsonb;
begin
  if iberia.admin_uid() is null then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  if p_signature is null or p_signature !~ '^data:image/png;base64,' then
    raise exception 'not a signature' using errcode = '22023';
  end if;
  if length(p_signature) > 400000 then
    raise exception 'signature too large' using errcode = '22023';
  end if;
  select * into cur from iberia.acts where id = p_id;
  if not found then return; end if;
  if p_rev is not null and cur.rev <> p_rev then return; end if;
  if cur.signature is not null then
    raise exception 'act is already signed' using errcode = '42501';
  end if;

  v_at := coalesce(p_signed_at, now());
  if v_at > now() then v_at := now(); v_claim := 'clamped-future'; end if;
  if v_at < now() - interval '30 days' then v_at := now(); v_claim := 'clamped-old'; end if;
  if p_signed_at is null then v_claim := 'server'; end if;

  select coalesce(nullif(name,''), nullif(email,'')) into who
    from public.profiles where id = iberia.admin_uid();
  select defs into v_defs from iberia.act_fields where only_row;

  update iberia.acts set
    signature = p_signature, signed_at = v_at, signed_by = iberia.admin_uid(),
    rep_name  = coalesce(nullif(p_rep_name,''), rep_name),
    field_defs = coalesce(v_defs, '{"header": [], "columns": []}'::jsonb),
    sign_log = sign_log || jsonb_build_object(
                 'at', to_char(v_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
                 'received', to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
                 'clock', v_claim, 'action', 'signed', 'witness', who,
                 'rep', coalesce(nullif(p_rep_name,''), rep_name)),
    rev = rev + 1, updated_at = now(), updated_by = iberia.admin_uid()
  where id = p_id;

  return query select * from iberia.acts_v where id = p_id;
end $$;


--
-- Name: sign_act_exec(uuid, bigint, uuid); Type: FUNCTION; Schema: iberia; Owner: -
--

CREATE FUNCTION iberia.sign_act_exec(p_id uuid, p_rev bigint, p_signature_id uuid) RETURNS SETOF iberia.acts_v
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  cur iberia.acts%rowtype;
  sig iberia.signatures%rowtype;
  who text;
begin
  if iberia.admin_uid() is null then
    raise exception 'not permitted' using errcode = '42501';
  end if;

  -- owner = iberia.admin_uid() in the WHERE is the whole access rule: you cannot
  -- apply a signature that is not yours because you cannot find one.
  select * into sig from iberia.signatures
   where id = p_signature_id and owner = iberia.admin_uid();
  if not found then
    raise exception 'that signature is not yours' using errcode = '42501';
  end if;

  select * into cur from iberia.acts where id = p_id;
  if not found then return; end if;
  if p_rev is not null and cur.rev <> p_rev then return; end if;

  select coalesce(nullif(name,''), nullif(email,'')) into who
    from public.profiles where id = iberia.admin_uid();

  update iberia.acts set
    exec_signature = sig.image,
    exec_name      = sig.label,
    exec_signed_at = now(),
    exec_signed_by = iberia.admin_uid(),
    sign_log = sign_log || jsonb_build_object(
                 'at', to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
                 'action', 'executor signed',
                 'witness', who,
                 'rep', sig.label),
    rev = rev + 1, updated_at = now(), updated_by = iberia.admin_uid()
  where id = p_id;

  return query select * from iberia.acts_v where id = p_id;
end $$;


--
-- Name: sync_project_columns(); Type: FUNCTION; Schema: iberia; Owner: -
--

CREATE FUNCTION iberia.sync_project_columns() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  card jsonb := coalesce(new.data->'card', '{}'::jsonb);
  s    text;
  e    text;
begin
  new.project_id := coalesce(card->>'projectId', '');
  new.client     := coalesce(card->>'client', '');
  new.site       := coalesce(card->>'site', '');
  new.pm         := coalesce(card->>'pm', '');
  new.currency   := coalesce(new.data->'settings'->>'currency', 'EUR');
  new.locked     := coalesce((new.data->>'locked')::boolean, false);

  -- the app stores '' for an unset date, which is not a date
  s := nullif(card->>'start', '');
  e := nullif(card->>'end', '');
  begin new.start_date := s::date; exception when others then new.start_date := null; end;
  begin new.end_date   := e::date; exception when others then new.end_date   := null; end;

  if TG_OP = 'INSERT' then
    new.created_by := iberia.admin_uid();
    new.rev := 1;
  else
    -- rev and the stamps belong to the server, never to the client
    new.rev := old.rev + 1;
    new.created_at := old.created_at;
    new.created_by := old.created_by;
  end if;
  new.updated_at := now();
  new.updated_by := iberia.admin_uid();
  return new;
end $$;


--
-- Name: unsign_act(uuid, bigint); Type: FUNCTION; Schema: iberia; Owner: -
--

CREATE FUNCTION iberia.unsign_act(p_id uuid, p_rev bigint) RETURNS SETOF iberia.acts_v
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare cur iberia.acts%rowtype; who text;
begin
  if iberia.admin_uid() is null then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  select * into cur from iberia.acts where id = p_id;
  if not found then return; end if;
  if p_rev is not null and cur.rev <> p_rev then return; end if;
  if cur.signature is null then return query select * from iberia.acts_v where id = p_id; return; end if;

  select coalesce(nullif(name,''), nullif(email,'')) into who
    from public.profiles where id = iberia.admin_uid();

  -- The executor's signature is NOT cleared here. It is a different line and
  -- a different person's assent; clearing the customer's is about reopening
  -- the sheet for editing, not about withdrawing ours.
  update iberia.acts set
    signature = null, signed_at = null, signed_by = null, field_defs = null,
    sign_log = sign_log || jsonb_build_object(
                 'at', to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
                 'action', 'cleared', 'witness', who, 'rep', cur.rep_name),
    rev = rev + 1, updated_at = now(), updated_by = iberia.admin_uid()
  where id = p_id;

  return query select * from iberia.acts_v where id = p_id;
end $$;


