--
-- Name: company_history_v; Type: VIEW; Schema: iberia; Owner: -
--

CREATE VIEW iberia.company_history_v AS
 SELECT h.id,
    h.entity,
    h.row_id,
    h.label,
    h.field,
    h.was,
    h.now,
    h.changed_at,
    COALESCE(pr.name, '—'::text) AS changed_by_name
   FROM (iberia.company_history h
     LEFT JOIN public.profiles pr ON ((pr.id = h.changed_by)))
  WHERE iberia.sees_payroll()
  ORDER BY h.changed_at DESC
 LIMIT 200;


